    public function sendMessage(int $senderId,int $recipientId,string $subject,string $body):int{$s=$this->pdo->prepare('SELECT id FROM players WHERE id=?');$s->execute([$recipientId]);if(!$s->fetch())throw new RuntimeException('Recipient not found');$s=$this->pdo->prepare('INSERT INTO messages(sender_id,recipient_id,subject,body) VALUES(?,?,?,?)');$s->execute([$senderId,$recipientId,$subject,$body]);$id=(int)$this->pdo->lastInsertId();$this->event($senderId,'message_sent',['message_id'=>$id]);return $id;}
    public function vacationSnapshot(int $playerId):array{$now=new DateTimeImmutable('now');$s=$this->pdo->prepare('SELECT p.vacation_until,ps.vacation_until protection_until,vs.active,vs.starts_at,vs.ends_at FROM players p LEFT JOIN protection_states ps ON ps.player_id=p.id LEFT JOIN vacation_states vs ON vs.player_id=p.id WHERE p.id=?');$s->execute([$playerId]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row)throw new RuntimeException('Player not found.');$until=$row['vacation_until']?:($row['ends_at']?:$row['protection_until']);$active=$until!==null&&new DateTimeImmutable((string)$until)>$now;return ['state'=>$active?'protected':'ready','active'=>$active,'starts_at'=>$row['starts_at'],'ends_at'=>$active?$until:null,'vacation_until'=>$active?$until:null,'cooldown'=>$this->cooldownState($playerId,'vacation_activation'),'blocking_operations'=>$this->blockingOperations($playerId),'formula'=>'vacation protection = account lock + fleet lock + colony production pause','states'=>['ready','protected','cooldown','success','error']];}
    private function cooldownState(int $playerId,string $key):array{$s=$this->pdo->prepare('SELECT available_at FROM player_cooldowns WHERE player_id=? AND cooldown_key=?');$s->execute([$playerId,$key]);$v=$s->fetchColumn();if(!$v)return ['state'=>'ready','available_at'=>null,'remaining_seconds'=>0];$remaining=max(0,(new DateTimeImmutable((string)$v))->getTimestamp()-(new DateTimeImmutable('now'))->getTimestamp());return $remaining>0?['state'=>'cooldown','available_at'=>$v,'remaining_seconds'=>$remaining]:['state'=>'ready','available_at'=>null,'remaining_seconds'=>0];}
    private function blockingOperations(int $playerId):array{$s=$this->pdo->prepare("SELECT mission_type,status,arrival_at,return_at FROM fleet_missions WHERE player_id=? AND status IN ('scheduled','outbound','arrived','returning') ORDER BY arrival_at LIMIT 20");$s->execute([$playerId]);$rows=$s->fetchAll(PDO::FETCH_ASSOC)?:[];return ['count'=>count($rows),'missions'=>$rows,'active_combat'=>count(array_filter($rows,fn(array $m)=>in_array($m['mission_type'],['attack','raid'],true)))>0];}
    public function activateVacation(int $playerId,int $days):void{if($playerId<1||$days<1||$days>30)throw new InvalidArgumentException('Vacation duration must be between 1 and 30 days.');$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT vacation_until FROM players WHERE id=? FOR UPDATE');$s->execute([$playerId]);$current=$s->fetchColumn();$now=new DateTimeImmutable('now');if($current!==false&&$current!==null&&new DateTimeImmutable((string)$current)>$now)throw new RuntimeException('Vacation mode is already active.');$cooldown=$this->cooldownState($playerId,'vacation_activation');if($cooldown['state']==='cooldown')throw new RuntimeException('Vacation activation is on cooldown for '.$cooldown['remaining_seconds'].' seconds.');$blocking=$this->blockingOperations($playerId);if($blocking['active_combat'])throw new RuntimeException('Vacation mode cannot start while attack or raid fleets are active.');$until=$now->modify('+'.$days.' days')->format('Y-m-d H:i:s');$starts=$now->format('Y-m-d H:i:s');$this->pdo->prepare('UPDATE players SET vacation_until=? WHERE id=?')->execute([$until,$playerId]);$this->pdo->prepare('INSERT INTO protection_states(player_id,vacation_until,protected_until) VALUES(?,?,?) ON DUPLICATE KEY UPDATE vacation_until=VALUES(vacation_until),protected_until=VALUES(protected_until)')->execute([$playerId,$until,$until]);$this->pdo->prepare('INSERT INTO vacation_states(player_id,active,starts_at,ends_at) VALUES(?,1,?,?) ON DUPLICATE KEY UPDATE active=1,starts_at=VALUES(starts_at),ends_at=VALUES(ends_at)')->execute([$playerId,$starts,$until]);$availableAt=$now->modify('+86400 seconds')->format('Y-m-d H:i:s');$this->pdo->prepare("INSERT INTO player_cooldowns(player_id,cooldown_key,available_at) VALUES(?, 'vacation_activation', ?) ON DUPLICATE KEY UPDATE available_at=VALUES(available_at)")->execute([$playerId,$availableAt]);$this->event($playerId,'vacation_enabled',['days'=>$days,'starts_at'=>$starts,'ends_at'=>$until,'cooldown_until'=>$availab