    public function refreshRanking():void{$this->pdo->exec('INSERT INTO rankings(player_id,overall_score,military_score,economy_score,covert_score) SELECT p.id,(r.attack_units+r.defense_units+r.unit_production*100+r.naquadah DIV 1000),(r.attack_units+r.defense_units),((r.naquadah+r.banked_naquadah) DIV 1000),(r.spies+r.anti_spies) FROM players p JOIN player_resources r ON r.player_id=p.id ON DUPLICATE KEY UPDATE overall_score=VALUES(overall_score),military_score=VALUES(military_score),economy_score=VALUES(economy_score),covert_score=VALUES(covert_score)');$this->pdo->exec('UPDATE rankings r JOIN (SELECT player_id,ROW_NUMBER() OVER(ORDER BY overall_score DESC) pos FROM rankings) x ON x.player_id=r.player_id SET r.rank_position=x.pos');}
    public function selectSector(int $playerId,int $sectorId):array{$s=$this->pdo->prepare('SELECT id,galaxy_id,sector_number,name,is_active FROM universe_sectors WHERE id=?');$s->execute([$sectorId]);$sector=$s->fetch(PDO::FETCH_ASSOC);if(!$sector||!(int)$sector['is_active'])throw new RuntimeException('Sector is unavailable or protected.');$map=$this->sectorSnapshot($playerId,$sectorId);if($map['state']==='protected')throw new RuntimeException('Sector visibility is protected.');$this->pdo->prepare("INSERT INTO game_events(player_id,event_type,payload) VALUES(?,?,?)")->execute([$playerId,'sector_selected',json_encode(['sector_id'=>(int)$sector['id'],'galaxy_id'=>(int)$sector['galaxy_id']])]);return $map;}
    public function sectorSnapshot(int $playerId,?int $sectorId=null):array{$rank=(int)($this->pdo->query('SELECT rank_level FROM players WHERE id='.(int)$playerId)->fetchColumn());if($rank<1)throw new RuntimeException('Sector scan requires an authenticated commander.');$shipStmt=$this->pdo->prepare('SELECT m.id,m.hull_level,m.shield_bays,m.exploration_level,COALESCE((SELECT SUM(mm.level) FROM mothership_modules mm WHERE mm.mothership_id=m.id AND (mm.module_key LIKE \'%sensor%\' OR mm.module_key LIKE \'%scan%\')),0) module_sensor FROM motherships m WHERE m.player_id=?');$shipStmt->execute([$playerId]);$ship=$shipStmt->fetch(PDO::FETCH_ASSOC);if(!$ship)return ['state'=>'protected','sector'=>null,'systems'=>[],'scan'=>['sensor_range'=>0,'mothership_science'=>0,'scan_technology'=>0,'power'=>0],'cooldown'=>$this->cooldownState($playerId,'sector_scan'),'formula'=>'sector scan = sensor range × mothership science × scan technology','states'=>['ready','empty','protected','cooldown','error']];$techStmt=$this->pdo->prepare("SELECT COALESCE(MAX(level),0) FROM player_technologies WHERE player_id=? AND technology_key IN ('sensor_array','scan','navigation','astrogation')");$techStmt->execute([$playerId]);$scanTech=max(1,(int)$techStmt->fetchColumn());$sensorRange=5+(int)$ship['hull_level']+(int)$ship['shield_bays']+(int)$ship['module_sensor'];$science=max(1,(int)$ship['exploration_level']+(int)$ship['module_sensor']);$power=$sensorRange*$science*max(1,$scanTech);$sectors=$this->pdo->query("SELECT s.id,s.galaxy_id,s.sector_number,s.name,s.sector_class,s.danger_level,s.resource_modifier,s.anomaly_rate,g.galaxy_number,g.name galaxy_name FROM universe_sectors s JOIN universe_galaxies g ON g.id=s.galaxy_id WHERE s.is_active=1 AND g.is_active=1 ORDER BY g.galaxy_number,s.sector_number")->fetchAll(PDO::FETCH_ASSOC)?:[];if(!$sectorId&&$sectors)$sectorId=(int)$sectors[0]['id'];$selected=null;foreach($sectors as $s)if((int)$s['id']===(int)$sectorId)$selected=$s;if(!$selected)return ['state