    public function selectGalaxy(int $playerId,int $galaxyId):array{$s=$this->pdo->prepare('SELECT id,galaxy_number,name,is_active FROM universe_galaxies WHERE id=?');$s->execute([$galaxyId]);$g=$s->fetch(PDO::FETCH_ASSOC);if(!$g||!(int)$g['is_active'])throw new RuntimeException('Galaxy is unavailable or protected.');$this->pdo->prepare("INSERT INTO game_events(player_id,event_type,payload) VALUES(?,?,?)")->execute([$playerId,'galaxy_selected',json_encode(['galaxy_id'=>(int)$g['id'],'galaxy_number'=>(int)$g['galaxy_number']])]);return $this->galaxySnapshot($playerId,$galaxyId);}
    public function galaxySnapshot(int $playerId,?int $galaxyId=null):array{$rank=(int)($this->pdo->query('SELECT rank_level FROM players WHERE id='.(int)$playerId)->fetchColumn());if($rank<1)throw new RuntimeException('Coordinate access requires an authenticated commander.');$galaxies=$this->pdo->query("SELECT g.id,g.galaxy_number,g.name,g.description,g.star_density,g.sector_count,g.system_count,COUNT(DISTINCT s.id) actual_sector_count,COUNT(DISTINCT ss.id) actual_system_count FROM universe_galaxies g LEFT JOIN universe_sectors s ON s.galaxy_id=g.id AND s.is_active=1 LEFT JOIN universe_solar_systems ss ON ss.sector_id=s.id WHERE g.is_active=1 GROUP BY g.id ORDER BY g.galaxy_number")->fetchAll(PDO::FETCH_ASSOC)?:[];if(!$galaxyId&&$galaxies)$galaxyId=(int)$galaxies[0]['id'];$selected=null;foreach($galaxies as $g)if((int)$g['id']===(int)$galaxyId)$selected=$g;if(!$selected)return ['state'=>'empty','galaxies'=>$galaxies,'selected'=>null,'sectors'=>[],'coordinate_scope'=>'none','scan_permission'=>false,'realm_ownership'=>['known_realms'=>0,'occupied_planets'=>0],'formula'=>'galaxy visibility = discovered sectors + scan permissions + coordinate scope','states'=>['ready','empty','protected','error']];$q=$this->pdo->prepare("SELECT s.id,s.sector_number,s.name,s.sector_class,s.danger_level,s.resource_modifier,s.anomaly_rate,COUNT(DISTINCT ss.id) system_count,COUNT(DISTINCT up.id) planet_count,COUNT(DISTINCT CASE WHEN ss.is_discovered=1 OR EXISTS(SELECT 1 FROM universe_discoveries ud WHERE ud.player_id=? AND ud.solar_system_id=ss.id) THEN ss.id END) discovered_system_count,COUNT(DISTINCT CASE WHEN up.is_occupied=1 THEN up.id END) occupied_planet_count FROM universe_sectors s LEFT JOIN universe_solar_systems ss ON ss.sector_id=s.id LEFT JOIN universe_planets up ON up.solar_system_id=ss.id WHERE s.galaxy_id=? AND s.is_active=1 GROUP BY s.id ORDER BY s.sector_number");$q->execute([$playerId,(int)$selected['id']]);$sectors=$q->fetchAll(PDO::FETCH_ASSOC)?:[];$owned=(int)$this->pdo->query('SELECT COUNT(*) FROM target_realms WHERE player_id='.(int)$playerId)->fetchColumn();$occupied=(int)$this->pdo->query("SELECT COUNT(*) FROM universe_planets up JOIN universe_solar_systems ss ON ss.id=up.solar_system_id JOIN universe_sectors s ON s.id=ss.sector_id WHERE s.galaxy_id=".(int)$selected['id']." AND up.is_occupied=1")->fetchColumn();$visible=count(array_filter($sectors,fn(array $s)=>(int)$s['discovered_system_count']>0||$rank>=3));$selected['actual_sector_count']=(int)$selected['actual_sector_count'];return ['state'=>$sectors?'ready':'empty','galaxies'=>$galaxies,'selected'=>$selected,'sectors'=>$sectors,'visible_sector_count'=>$visible,'coordinate_scope'=>'galaxy:'.(int)$selected['galaxy_number'].':*','scan_permission'=>$rank>=1,'realm_ownership'=>['known_realms'=>$owned,'occupied_planets'=>$occupied],'filters'=>['all'=>count($sectors),'discovered'=>$visible,'danger_levels'=>array_values(array_unique(array_map(fn(array $s)=>(int)$s['danger_level'],$sectors)))],'formula'=>'galaxy visibility = discovered sectors + scan permissions + coordinate scope','states'=>['ready','empty','protected','error']];}
