    public function ascensionSnapshot(int $playerId):array{$cfg=$this->ascensionSettings();$s=$this->pdo->prepare('SELECT p.glory,p.reputation,p.ascension_count,pe.tier_number,pe.level_number,pe.experience,ast.ascension_points,ast.ascended_race,ast.last_ascended_at FROM players p LEFT JOIN progression_entities pe ON pe.player_id=p.id AND pe.entity_category=\'player\' AND pe.entity_key=\'player_core\' LEFT JOIN ascension_states ast ON ast.player_id=p.id WHERE p.id=?');$s->execute([$playerId]);$p=$s->fetch(PDO::FETCH_ASSOC);if(!$p)throw new RuntimeException('Player not found.');$techKeys=['siege','fortification','infiltration','detection'];$q=$this->pdo->prepare('SELECT technology_key,level FROM player_technologies WHERE player_id=? AND technology_key IN (\'siege\',\'fortification\',\'infiltration\',\'detection\')');$q->execute([$playerId]);$tech=array_fill_keys($techKeys,0);foreach($q->fetchAll(PDO::FETCH_ASSOC)?:[] as $row)$tech[$row['technology_key']]=(int)$row['level'];$required=(int)$cfg['technology_level'];$completed=(int)($p['tier_number']??0)>=$cfg['min_tier']&&(int)($p['level_number']??0)>=$cfg['min_level'];$techReady=count(array_filter($tech,fn(int $v)=>$v>=$required))===count($tech);$cd=$this->cooldownState($playerId,'ascension');$eligible=$completed&&(int)$p['glory']>=$cfg['min_glory']&&(int)$p['reputation']>=$cfg['min_reputation']&&$techReady&&$cd['state']==='ready';$mastery=max(0,(int)($p['tier_number']??0)*(int)($p['level_number']??0));$reward=(int)round($mastery*$cfg['glory_multiplier']);return ['state'=>$eligible?'ready':($cd['state']==='cooldown'?'cooldown':'locked'),'eligible'=>$eligible,'player'=>['glory'=>(int)$p['glory'],'reputation'=>(int)$p['reputation'],'ascension_count'=>(int)($p['ascension_count']??0)],'progression'=>['tier'=>(int)($p['tier_number']??0),'level'=>(int)($p['level_number']??0),'experience'=>(int)($p['experience']??0),'mastery'=>$mastery],'requirements'=>['tier'=>(int)$cfg['min_tier'],'level'=>(int)$cfg['min_level'],'glory'=>(in