    public function ascend(int $playerId,string $ascendedRace):void{$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT p.glory,p.reputation,p.ascension_count,pe.tier_number,pe.level_number FROM players p LEFT JOIN progression_entities pe ON pe.player_id=p.id AND pe.entity_category=\'player\' AND pe.entity_key=\'player_core\' WHERE p.id=? FOR UPDATE');$s->execute([$playerId]);$p=$s->fetch(PDO::FETCH_ASSOC);if(!$p)throw new RuntimeException('Player not found.');$cfg=$this->ascensionSettings();$cd=$this->cooldownState($playerId,'ascension');if($cd['state']==='cooldown')throw new RuntimeException('Ascension is on cooldown for '.$cd['remaining_seconds'].' seconds.');if((int)($p['tier_number']??0)<$cfg['min_tier']||(int)($p['level_number']??0)<$cfg['min_level'])throw new RuntimeException('Complete the maximum tier and level before ascending.');if((int)$p['glory']<$cfg['min_glory']||(int)$p['reputation']<$cfg['min_reputation'])throw new RuntimeException('Glory and Reputation requirements are not met.');$tech=$this->pdo->prepare("SELECT COUNT(*) FROM player_technologies WHERE player_id=? AND technology_key IN ('siege','fortification','infiltration','detection') AND level>=?");$tech->execute([$playerId,(int)$cfg['technology_level']]);if((int)$tech->fetchColumn()<4)throw new RuntimeException('Required technologies are not complete.');$mastery=(int)$p['tier_number']*(int)$p['level_number'];$reward=(int)round($mastery*$cfg['glory_multiplier']);$glory=(int)$p['glory']-(int)$cfg['min_glory'];$rep=(int)$p['reputation']-(int)$cfg['min_reputation'];$this->pdo->prepare('UPDATE players SET glory=?,reputation=?,ascension_count=ascension_count+1,rank_level=4,rank_name=\'Ascended\' WHERE id=?')->execute([$glory,$rep,$playerId]);$this->pdo->prepare('INSERT INTO glory_reputation(player_id,glory,reputation) VALUES(?,?,?) ON DUPLICATE KEY UPDATE glory=VALUES(glory),reputation=VALUES(reputation)')->execute([$playerId,$glory,$rep]);$this->pdo->prepare('INSERT INTO ascensions(player_id,ascended_race,glory_spent,reputation_spent,conversion_value,title_granted) VALUES(?,?,?,?,?,?)')->execute([$playerId,$ascendedRace,(int)$cfg['min_glory'],(int)$cfg['min_reputation'],$reward,'Ascended']);$this->pdo->prepare('INSERT INTO ascension_states(player_id,ascension_count,ascended_race,ascension_points,last_ascended_at) VALUES(?,1,?,?,NOW()) ON DUPLICATE KEY UPDATE ascension_count=ascension_count+1,ascended_race=VALUES(ascended_race),ascension_points=ascension_points+VALUES(ascension_points),last_ascended_at=NOW()')->execute([$playerId,$ascendedRace,$reward]);$this->pdo->prepare("UPDATE progression_entities SET tier_number=1,level_number=1,experience=0 WHERE player_id=? AND entity_category='player' AND entity_key='player_core'")->execute([$playerId]);$availableAt=(new DateTimeImmutable('now'))->modify('+'.(int)$cfg['cooldown_seconds'].' seconds')->format('Y-m-d H:i:s');$this->pdo->prepare("INSERT INTO player_cooldowns(player_id,cooldown_key,available_at) VALUES(?, 'ascension', ?) ON DUPLICATE KEY UPDATE available_at=VALUES(available_at)")->execute([$playerId,$availableAt]);$this->event($playerId,'ascended',['race'=>$ascendedRace,'mastery'=>$mastery,'reward'=>$reward,'cooldown_until'=>$availableAt]);$this->pdo->commit();}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function solarSystemSnapshot(int $playerId,?int $systemId=null):array{$rank=(int)($this->pdo->query('SELECT rank_level FROM players WHERE id='.(int)$playerId)->fetchColumn());if($rank<1)throw new RuntimeException('Solar-system access requires an authenticated commander.');$systems=$this->pdo->query("SELECT ss.id,ss.sector_id,ss.system_number,ss.name,ss.spectral_class,ss.star_age_billion,ss.star_mass,ss.system_class,ss.max_orbits,ss.travel_modifier,ss.is_discovered,s.sector_number,s.name sector_name,s.danger_level,s.anomaly_rate,g.galaxy_number,g.name galaxy_name FROM universe_solar_systems ss JOIN universe_sectors s ON s.id=ss.sector_id JOIN universe_galaxies g ON g.id=s.galaxy_id WHERE s.is_active=1 AND g.is_active=1 ORDER BY g.galaxy_number,s.sector_number,ss.system_number")->fetchAll(PDO::FETCH_ASSOC)?:[];if(!$systemId&&$systems)$systemId=(int)$systems[0]['id'];$system=null;foreach($systems as $x)if((int)$x['id']===(int)$systemId)$system=$x;if(!$system)return ['state'=>'empty','system'=>null,'systems'=>$systems,'planets'=>[],'fleet_lanes'=>[],'gate'=>['available'=>false,'level'=>0,'status'=>'OFFLINE'],'telemetry'=>['sensor_range'=>0,'mothership_science'=>0,'discovery'=>false,'scan_power'=>0],'cooldown'=>['state'=>'ready','remaining_seconds'=>0],'formula'=>'system access = coordinate validity + discovery state + gate availability','states'=>['ready','empty','protected','error']];$d=$this->pdo->prepare('SELECT id FROM universe_discoveries WHERE player_id=? AND solar_system_id=? LIMIT 1');$d->execute([$playerId,(int)$system['id']]);$discovered=(bool)$d->fetchColumn()||(int)$system['is_discovered']===1;$ship=$this->pdo->prepare("SELECT m.hull_level,m.shield_bays,m.exploration_level,COALESCE((SELECT SUM(mm.level) FROM mothership_modules mm WHERE mm.mothership_id=m.id AND (mm.module_key LIKE '%sensor%' OR mm.module_key LIKE '%scan%')),0) module_sensor FROM motherships m WHERE m.player_id=?");$ship->execute([$playerId]);$m=$ship->fetch(PDO::FETCH_ASSOC)?:['hull_level'=>0,'shield_bays'=>0,'exploration_level'=>0,'module_sensor'=>0];$sensor=5+(int)$m['hull_level']+(int)$m['shield_bays']+(int)$m['module_sensor'];$science=max(1,(int)$m['exploration_level']+(int)$m['module_sensor']);$telemetry=['sensor_range'=>$sensor,'mothership_science'=>$science,'discovery'=>$discovered,'scan_power'=>$sensor*$science];$p=$this->pdo->prepare('SELECT p.id,p.orbit_position,p.name,p.coordinate_label,p.planet_class,p.planet_type,p.biome,p.size_class,p.habitability,p.slots,p.anomaly_rate,p.is_colonizable,p.is_occupied,COUNT(DISTINCT m.id) moon_count,COALESCE(MAX(m.jump_gate_level),0) gate_level FROM universe_planets p LEFT JOIN universe_moons m ON m.planet_id=p.id WHERE p.solar_system_id=? GROUP BY p.id ORDER BY p.orbit_position');$p->execute([(int)$system['id']]);$planets=$p->fetchAll(PDO::FETCH_ASSOC)?:[];foreach($planets as &$planet){$ms=$this->pdo->prepare('SELECT id,orbit_position,name,moon_class,moon_type,biome,sensor_range_bonus,jump_gate_level,is_occupied FROM universe_moons WHERE planet_id=? ORDER BY orbit_position');$ms->execute([(int)$planet['id']]);$planet['moons']=$ms->fetchAll(PDO::FETCH_ASSOC);}unset($planet);$gateLevel=0;foreach($planets as $planet)$gateLevel=max($gateLevel,(int)$planet['gate_level']);$gate=['available'=>$discovered&&$gateLevel>0,'level'=>$gateLevel,'status'=>$gateLevel>0?'ONLINE':'OFFLINE'];$fleet=$this->pdo->prepare("SELECT id,mission_type,status,departure_at,arrival_at,return_at,payload FROM fleet_missions WHERE player_id=? AND status IN ('scheduled','outbound','arrived','returning') AND JSON_EXTRACT(payload,'$.system_id')=? ORDER BY arrival_at");$fleet->execute([$playerId,(int)$system['id']]);$lanes=$fleet->fetchAll(PDO::FETCH_ASSOC)?:[];$system['discovered']=$discovered;$system['coordinate']=$system['galaxy_number'].':'.$system['sector_number'].':'.$system['system_number'];return ['state'=>$discovered?'ready':'protected','system'=>$system,'systems'=>$systems,'planets'=>$planets,'fleet_lanes'=>$lanes,'gate'=>$gate,'telemetry'=>$telemetry,'cooldown'=>$this->cooldownState($playerId,'anomaly_explore'),'formula'=>'system access = coordinate validity + discovery state + gate availability','states'=>['ready','empty','protected','error']];}
    public function exploreAnomaly(int $playerId,int $systemId):array{$this->pdo->beginTransaction();try{$s=$this->pdo->prepare("SELECT ss.id,ss.name,ss.is_discovered,s.danger_level,s.anomaly_rate FROM universe_solar_systems ss JOIN universe_sectors s ON s.id=ss.sector_id JOIN universe_galaxies g ON g.id=s.galaxy_id WHERE ss.id=? AND s.is_active=1 AND g.is_active=1 FOR UPDATE");$s->execute([$systemId]);$system=$s->fetch(PDO::FETCH_ASSOC);if(!$system)throw new RuntimeException('Solar system coordinate is invalid.');$cool=$this->cooldownState($playerId,'anomaly_explore');if($cool['state']==='cooldown')throw new RuntimeException('Anomaly exploration is on cooldown for '.$cool['remaining_seconds'].' seconds.');$d=$this->pdo->prepare('SELECT id FROM universe_discoveries WHERE player_id=? AND discovery_key=?');$d->execute([$playerId,'system:'.$systemId.':anomaly']);if($d->fetchColumn())throw new RuntimeException('This anomaly has already been explored.');$ship=$this->pdo->prepare("SELECT m.hull_level,m.shield_bays,m.exploration_level,COALESCE((SELECT SUM(mm.level) FROM mothership_modules mm WHERE mm.mothership_id=m.id AND (mm.module_key LIKE '%sensor%' OR mm.module_key LIKE '%scan%')),0) module_sensor FROM motherships m WHERE m.player_id=? FOR UPDATE");$ship->execute([$playerId]);$m=$ship->fetch(PDO::FETCH_ASSOC);if(!$m)throw new RuntimeException('Mothership readiness is required.');$power=(5+(int)$m['hull_level']+(int)$m['shield_bays']+(int)$m['module_sensor'])*max(1,(int)$m['exploration_level']+(int)$m['module_sensor']);$success=$power>=((int)$system['danger_level']*10);if(!$success)throw new RuntimeException('Scan telemetry is insufficient for this anomaly.');$reward=(int)round(1000*(1+(float)$system['anomaly_rate']));$payload=['system_id'=>$systemId,'risk'=>(int)$system['danger_level'],'anomaly_rate'=>(float)$system['anomaly_rate'],'reward_naquadah'=>$reward,'scan_power'=>$power];$this->pdo->prepare('INSERT INTO universe_discoveries(player_id,solar_system_id,discovery_type,discovery_key,payload) VALUES(?,?,\'anomaly\',?,?)')->execute([$playerId,$systemId,'system:'.$systemId.':anomaly',json_encode($payload)]);$this->pdo->prepare('UPDATE player_resources SET naquadah=naquadah+? WHERE player_id=?')->execute([$reward,$playerId]);$now=new DateTimeImmutable('now');$until=$now->modify('+3600 seconds')->format('Y-m-d H:i:s');$this->pdo->prepare("INSERT INTO player_cooldowns(player_id,cooldown_key,available_at) VALUES(?, 'anomaly_explore', ?) ON DUPLICATE KEY UPDATE available_at=VALUES(available_at)")->execute([$playerId,$until]);$this->event($playerId,'anomaly_discovered',['system_id'=>$systemId,'reward_naquadah'=>$reward,'scan_power'=>$power]);$this->pdo->commit();return ['state'=>'success','system_id'=>$systemId,'reward_naquadah'=>$reward,'cooldown'=>$this->cooldownState($playerId,'anomaly_explore'),'payload'=>$payload];}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function universePlanetsSnapshot(int $playerId,?int $planetId=null):array{$rank=(int)($this->pdo->query('SELECT rank_level FROM players WHERE id='.(int)$playerId)->fetchColumn());if($rank<1)throw new RuntimeException('Universe planet access requires an authenticated commander.');$q=$this->pdo->query("SELECT p.id,p.solar_system_id,p.orbit_position,p.name,p.coordinate_label,p.planet_class,p.planet_type,p.biome,p.size_class,p.habitability,p.slots,p.metal_modifier,p.crystal_modifier,p.energy_modifier,p.food_modifier,p.water_modifier,p.anomaly_rate,p.is_colonizable,p.is_occupied,ss.system_number,ss.name system_name,s.sector_number,g.galaxy_number,g.name galaxy_name,COUNT(DISTINCT pc.id) colony_count FROM universe_planets p JOIN universe_solar_systems ss ON ss.id=p.solar_system_id JOIN universe_sectors s ON s.id=ss.sector_id JOIN universe_galaxies g ON g.id=s.galaxy_id LEFT JOIN player_colonies pc ON pc.planet_id=p.id AND pc.player_id=".(int)$playerId." WHERE s.is_active=1 AND g.is_active=1 GROUP BY p.id ORDER BY g.galaxy_number,s.sector_number,ss.system_number,p.orbit_position");$planets=$q->fetchAll(PDO::FETCH_ASSOC)?:[];$tech=$this->pdo->prepare("SELECT COALESCE(MAX(level),0) FROM player_technologies WHERE player_id=? AND technology_key IN ('life_support','water_recycling','agriculture','terraforming')");$tech->execute([$playerId]);$lifeLevel=(int)$tech->fetchColumn();$lifeSupport=1+($lifeLevel*0.05);foreach($planets as &$p){$p['coordinate']=$p['galaxy_number'].':'.$p['sector_number'].':'.$p['system_number'].':'.$p['orbit_position'];$p['infrastructure_factor']=1.0;$p['life_support_factor']=round($lifeSupport,3);$p['colonization_capacity']=(int)floor((int)$p['slots']*$p['infrastructure_factor']*$p['life_support_factor']);$p['eligible']=(int)$p['is_colonizable']===1&&(int)$p['is_occupied']===0&&(float)$p['habitability']>=0.25&&(int)$p['colony_count']===0;$m=$this->pdo->prepare('SELECT id,orbit_position,name,moon_class,moon_type,biome,jump_gate_level,is_occupied FROM universe_moons WHERE planet_id=? ORDER BY orbit_position');$m->execute([(int)$p['id']]);$p['moons']=$m->fetchAll(PDO::FETCH_ASSOC)?:[];}unset($p);$selected=null;foreach($planets as $p)if((int)$p['id']===(int)$planetId)$selected=$p;if(!$selected&&$planets)$selected=$planets[0];$cd=$this->cooldownState($playerId,'planet_colonize');return ['state'=>$planets?'ready':'empty','selected'=>$selected,'planets'=>$planets,'life_support_level'=>$lifeLevel,'life_support_factor'=>$lifeSupport,'cooldown'=>$cd,'formula'=>'colonization capacity = planet slots × infrastructure × life-support technology','states'=>['ready','empty','protected','insufficient-resource','success','error']];}
    public function getPlanetDetails(int $planetId):array{$s=$this->pdo->prepare('SELECT p.*,ss.system_number,ss.name system_name,s.sector_number,g.galaxy_number,g.name galaxy_name FROM universe_planets p JOIN universe_solar_systems ss ON ss.id=p.solar_system_id JOIN universe_sectors s ON s.id=ss.sector_id JOIN universe_galaxies g ON g.id=s.galaxy_id WHERE p.id=?');$s->execute([$planetId]);$planet=$s->fetch(PDO::FETCH_ASSOC);if(!$planet)throw new RuntimeException('Planet not found.');$m=$this->pdo->prepare('SELECT * FROM universe_moons WHERE planet_id=? ORDER BY orbit_position');$m->execute([$planetId]);$planet['moons']=$m->fetchAll(PDO::FETCH_ASSOC)?:[];return $planet;}
